// Lo que str.isspace() considera espacio. `trim()` de JS difiere (﻿, \x1c-\x1f).
const ESPACIO_PY = "\\t\\n\\x0b\\x0c\\r\\x1c-\\x1f \\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
