    else if (c === comilla) salida += "\\" + c;
    else if (c === "\n") salida += "\\n";
    else if (c === "\r") salida += "\\r";
    else if (c === "\t") salida += "\\t";
    else if (c !== " " && NO_IMPRIMIBLE.test(c)) {
      if (cp < 0x100) salida += "\\x" + cp.toString(16).padStart(2, "0");
      else if (cp < 0x10000) salida += "\\u" + cp.toString(16).padStart(4, "0");
      else salida += "\\U" + cp.toString(16).padStart(8, "0");
    } else salida += c;
  }
  return comilla + salida + comilla;
}

/** Minúsculas y sin tildes: "Común" y "comun" tienen que ser lo mismo. */
function normalizar(texto) {
  return texto.normalize("NFKD").replace(/\p{M}/gu, "").toLowerCase();
}

function contieneFrase(textoNormalizado, frase) {
  const patron = new RegExp(BORDE + escaparRegex(normalizar(frase)) + BORDE, "u");
  return patron.test(textoNormalizado);
}

// --- Montos (verificacion.py) -----------------------------------------------
//
// Un monto es un string decimal canónico igual a str(Decimal) de Python
// ("12.50", "1200", "0.00"). Para comparar se pasa a centavos con BigInt: nunca
// punto flotante, por la misma razón que storage/dinero.py.

const NUMERO = /\d{1,3}(?:[.,]\d{3})+(?:[.,]\d{1,2})?|\d+(?:[.,]\d{1,2})?/g;

function sinSeparadorDeMiles(entero, sep) {
  if (!entero.includes(sep)) return entero;
  if (!new RegExp(`^\\d{1,3}(?:${escaparRegex(sep)}\\d{3})+$`).test(entero)) return null;
  return entero.split(sep).join("");
}

function combinar(entero, decimales, milesSep) {
  if (!/^\d{1,2}$/.test(decimales)) return null; // el dólar no tiene tres decimales
  const enteroLimpio = sinSeparadorDeMiles(entero, milesSep);
  if (enteroLimpio === null || !/^\d+$/.test(enteroLimpio)) return null;
  return `${enteroLimpio}.${decimales}`;
}

function rpartition(texto, sep) {
  const i = texto.lastIndexOf(sep);
  return [texto.slice(0, i), texto.slice(i + sep.length)];
}

function canonico(normalizado) {
  const [entero, decimales] = normalizado.split(".");
  const sinCeros = entero.replace(/^0+/, "") || "0";
  return decimales === undefined ? sinCeros : `${sinCeros}.${decimales}`;
}

/** Convierte un número escrito por una persona a string decimal canónico, o null. */
function parsearMonto(texto) {
  const limpio = strip(texto).split(" ").join("").split("$").join("");
  if (!limpio || !/^[\d.,]+$/.test(limpio)) return null;

  const tienePunto = limpio.includes(".");
  const tieneComa = limpio.includes(",");
  let normalizado;
  if (tienePunto && tieneComa) {
    const decimalSep = limpio.lastIndexOf(".") > limpio.lastIndexOf(",") ? "." : ",";
    const [entero, decimales] = rpartition(limpio, decimalSep);
    normalizado = combinar(entero, decimales, decimalSep === "." ? "," : ".");
  } else if (tienePunto || tieneComa) {
    const sep = tienePunto ? "." : ",";
    const [entero, resto] = rpartition(limpio, sep);
    normalizado =
      resto.length === 3 // "1.200" son mil doscientos, no uno coma dos
        ? sinSeparadorDeMiles(limpio, sep)
        : combinar(entero, resto, sep);
  } else {
    normalizado = limpio;
  }
  return normalizado === null ? null : canonico(normalizado);
}

function aCentavosExactos(monto) {
  const [entero, decimales = ""] = monto.split(".");
  return BigInt(entero) * 100n + BigInt(decimales.padEnd(2, "0") || "0");
}

/** Todos los números que una persona escribió en el mensaje, en centavos. */
function montosEnTexto(texto) {
  const encontrados = new Set();
  for (const m of texto.matchAll(NUMERO)) {
    const monto = parsearMonto(m[0]);
    if (monto !== null) encontrados.add(aCentavosExactos(monto));
  }
  return encontrados;
}

/** ¿El monto que devolvió el LLM está realmente escrito en el mensaje? */
function montoRespaldadoPorTexto(monto, texto) {
  return montosEnTexto(texto).has(aCentavosExactos(monto));
}

/** Para guardar (storage/dinero.py). Falla rápido con montos no positivos. */
function aCentavos(monto) {
  const centavos = aCentavosExactos(monto);
  if (centavos <= 0n) throw new Error(`El monto debe ser positivo, llegó ${monto}`);
  if (centavos > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error(`El monto ${monto} es demasiado grande para guardarse`);
  }
  return Number(centavos);
}

// --- Fechas: date.fromisoformat de Python -----------------------------------
//
// Una fecha es un número de día (días desde 1970-01-01, UTC). Acepta los mismos
// formatos que Python 3.12: YYYY-MM-DD, YYYYMMDD, YYYY-Www[-D], YYYYWww[D].

const MS_POR_DIA = 86_400_000;

function diaDe(anio, mes, dia) {
  const d = new Date(0);
  d.setUTCFullYear(anio, mes - 1, dia);
  return Math.round(d.getTime() / MS_POR_DIA);
}

function aIso(numeroDeDia) {
  const d = new Date(numeroDeDia * MS_POR_DIA);
  const anio = String(d.getUTCFullYear()).padStart(4, "0");
  const mes = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dia = String(d.getUTCDate()).padStart(2, "0");
  return `${anio}-${mes}-${dia}`;
}

function esBisiesto(anio) {
  return anio % 4 === 0 && (anio % 100 !== 0 || anio % 400 === 0);
}

function diasDelMes(anio, mes) {
  return [31, esBisiesto(anio) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mes - 1];
}

function diaDeLaSemana(numeroDeDia) {
  return (((numeroDeDia + 3) % 7) + 7) % 7; // lunes = 0; 1970-01-01 fue jueves
}

/** Número de día o null si no es una fecha que Python aceptaría. */
function fechaDesdeIso(texto) {
  let m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(texto) || /^(\d{4})(\d{2})(\d{2})$/.exec(texto);
  if (m) {
    const [anio, mes, dia] = m.slice(1).map(Number);
    if (anio < 1 || mes < 1 || mes > 12 || dia < 1 || dia > diasDelMes(anio, mes)) return null;
    return diaDe(anio, mes, dia);
  }
  m = /^(\d{4})-W(\d{2})(?:-(\d))?$/.exec(texto) || /^(\d{4})W(\d{2})(\d)?$/.exec(texto);
  if (m) {
    const anio = Number(m[1]);
    const semana = Number(m[2]);
    const dia = m[3] === undefined ? 1 : Number(m[3]);
    if (anio < 1) return null;
    const primeroDeEnero = diaDeLaSemana(diaDe(anio, 1, 1));
    const tiene53 = primeroDeEnero === 3 || (primeroDeEnero === 2 && esBisiesto(anio));
    if (semana < 1 || semana > 53 || (semana === 53 && !tiene53)) return null;
    if (dia < 1 || dia > 7) return null;
    const cuatroDeEnero = diaDe(anio, 1, 4);
    const lunesSemana1 = cuatroDeEnero - diaDeLaSemana(cuatroDeEnero);
    return lunesSemana1 + (semana - 1) * 7 + (dia - 1);
  }
  return null;
}

// --- Taxonomía (categorias.py) ----------------------------------------------
//
// Recibe el JSON de n8n/taxonomia.json, que ya pasó las validaciones de Python.

function crearTaxonomia(datos) {
  const activas = datos.categorias.filter((c) => !c.candidata);
  const nombres = activas.map((c) => c.nombre);
  const compartida = datos.atribuciones.find((a) => a.compartida);
  const personas = datos.atribuciones.filter((a) => !a.compartida).map((a) => a.nombre);
  const etiquetas = Object.fromEntries(datos.atribuciones.map((a) => [a.nombre, a.etiqueta]));

  function expresiones(persona, remitente) {
    const atribucion = datos.atribuciones.find((a) => a.nombre === persona);
    return (atribucion && atribucion.como_lo_llaman[remitente]) || [];
  }

  function mencionaA(persona, remitente, texto) {
    const normalizado = normalizar(texto);
    return expresiones(persona, remitente).some((e) => contieneFrase(normalizado, e));
  }

  function mencionaAlguna(texto, frases) {
    const normalizado = normalizar(texto);
    return frases.some((f) => contieneFrase(normalizado, f));
  }

  function mencionaGastoCompartido(texto) {
    return mencionaAlguna(texto, compartida.marcadores);
  }

  const bolsillos = datos.presupuesto ? datos.presupuesto.bolsillos : [];

  return {
    fallback: datos.fallback,
    nombres,
    personas,
    etiquetas,
    compartida,
    nombresAtribucion: datos.atribuciones.map((a) => a.nombre),
    contiene: (nombre) =>
      typeof nombre === "string" && nombres.includes(strip(nombre).toLowerCase()),
    describirParaPrompt: () =>
      activas
        .map(
          (c) =>
            `- ${c.nombre}: ${c.descripcion}` +
            (c.ejemplos.length ? ` Ej.: ${c.ejemplos.join(", ")}.` : ""),
        )
        .join("\n"),
    expresiones,
    mencionaA,
    mencionaGastoCompartido,
    /** Resolución determinista de parentescos: "mi hija" según quién escribe. */
    personasEn: (cita, remitente) =>
      personas.filter((p) => p !== remitente && mencionaA(p, remitente, cita)),
    esCompartida: (cita) =>
      strip(normalizar(cita)) === compartida.nombre || mencionaGastoCompartido(cita),
    bolsillos,
    /**
     * Contra qué bolsillo cuenta un gasto, o null (categorias.py: bolsillo_de).
     * Un marcador ("del fondo") gana sobre la categoría si apunta a un solo bolsillo.
     */
    bolsilloDe: (categoria, texto) => {
      const porMarcador = bolsillos.filter((b) => mencionaAlguna(texto, b.marcadores));
      if (porMarcador.length === 1) return porMarcador[0].nombre;
      const deCategoria = bolsillos.find((b) => b.categorias.includes(categoria));
      return deCategoria ? deCategoria.nombre : null;
    },
  };
}

// --- Contrato de la respuesta del LLM (schema.py: RespuestaLLM) --------------

const CAMPOS_OPCIONALES = ["monto", "categoria", "fecha", "quien_paga"];
const CAMPOS_CONFIANZA = [
  "confianza_monto",
  "confianza_categoria",
  "confianza_fecha",
  "confianza_quien_paga",
];

/** Valida la afirmación cruda. Lanza ErrorDeExtraccion si no respeta el contrato. */
function validarRespuesta(respuesta) {
  if (respuesta === null || typeof respuesta !== "object" || Array.isArray(respuesta)) {
    throw new ErrorDeExtraccion("El LLM no respetó el contrato: no es un objeto");
  }
  const problemas = [];
  for (const campo of CAMPOS_OPCIONALES) {
    const valor = respuesta[campo];
    if (valor !== undefined && valor !== null && typeof valor !== "string") {
      problemas.push(`${campo} debe ser texto o null`);
    }
  }
  if (typeof respuesta.descripcion !== "string") problemas.push("falta descripcion");
  for (const campo of CAMPOS_CONFIANZA) {
    if (!CONFIANZAS.includes(respuesta[campo])) problemas.push(`${campo} inválida`);
  }
  if (problemas.length) {
    throw new ErrorDeExtraccion(`El LLM no respetó el contrato: ${problemas.join("; ")}`);
  }
  const limpia = {};
  for (const campo of CAMPOS_OPCIONALES) limpia[campo] = respuesta[campo] ?? null;
  limpia.descripcion = respuesta.descripcion;
  for (const campo of CAMPOS_CONFIANZA) limpia[campo] = respuesta[campo];
  return limpia;
}

// --- Reglas por campo (parser.py) --------------------------------------------

function verificarMontoDe(respuesta, texto, notas) {
  const nota = (t) => notas.push({ campo: "monto", texto: t });
  if (respuesta.monto === null) {
    nota("El mensaje no trae un monto.");
    return [null, "baja"];
  }
  const monto = parsearMonto(respuesta.monto);
  if (monto === null) {
    nota(`No pude leer ${repr(respuesta.monto)} como un número.`);
    return [null, "baja"];
  }
  if (aCentavosExactos(monto) <= 0n) {
    nota(`El monto ${monto} no es positivo.`);
    return [null, "baja"];
  }
  if (!montoRespaldadoPorTexto(monto, texto)) {
    // Un número que nadie escribió no se acepta, por seguro que se declare.
    nota(`El monto ${monto} no aparece en el mensaje original.`);
    return [monto, "baja"];
  }
  return [monto, respuesta.confianza_monto];
}

function verificarCategoriaDe(respuesta, taxonomia, notas) {
  if (!taxonomia.contiene(respuesta.categoria)) {
    notas.push({
      campo: "categoria",
      texto:
        `La categoría ${repr(respuesta.categoria)} no está en la lista; ` +
        `queda como ${repr(taxonomia.fallback)}.`,
    });
    return [taxonomia.fallback, "baja"];
  }
  return [strip(respuesta.categoria).toLowerCase(), respuesta.confianza_categoria];
}

function verificarFechaDe(respuesta, hoy, notas) {
  const nota = (t) => notas.push({ campo: "fecha", texto: t });
  if (respuesta.fecha === null) {
    nota("El mensaje no menciona fecha; se asume hoy.");
    return [hoy, "media"];
  }
  const fecha = fechaDesdeIso(respuesta.fecha);
  if (fecha === null) {
    nota(`No pude leer ${repr(respuesta.fecha)} como fecha; se asume hoy.`);
    return [hoy, "baja"];
  }
  if (fecha > hoy) {
    nota(`La fecha ${aIso(fecha)} está en el futuro.`);
    return [fecha, "baja"];
  }
  if (hoy - fecha > ANTIGUEDAD_MAXIMA_DIAS) {
    nota(`La fecha ${aIso(fecha)} tiene más de un año.`);
    return [fecha, "baja"];
  }
  return [fecha, respuesta.confianza_fecha];
}

/**
 * Quién asume el costo. El LLM cita la frase; acá se resuelve con la tabla del
 * yaml según quién escribe. Por defecto, el remitente, nunca con confianza alta.
 */
function resolverAtribucion(respuesta, texto, remitente, taxonomia, notas) {
  const nota = (t) => notas.push({ campo: "atribuido_a", texto: t });
  const cita = respuesta.quien_paga;
  const confianza = respuesta.confianza_quien_paga;

  if (cita === null || !strip(cita)) {
    if (confianza === "baja") {
      nota("No queda claro quién asume este gasto; por ahora quedó como tuyo.");
      return [remitente, "baja"];
    }
    nota("El mensaje no dice de quién es el gasto; asumí que es tuyo porque lo escribiste tú.");
    return [remitente, "media"];
  }

  const compartida = taxonomia.compartida.nombre;
  if (taxonomia.esCompartida(cita)) {
    if (!taxonomia.mencionaGastoCompartido(texto)) {
      nota("El mensaje no dice explícitamente que sea un gasto compartido.");
      return [compartida, "baja"];
    }
    return [compartida, confianza];
  }

  const personas = taxonomia.personasEn(cita, remitente);
  if (personas.length > 1) {
    nota(`${repr(cita)} nombra a más de una persona; por ahora quedó como tuyo.`);
    return [remitente, "baja"];
  }
  if (personas.length === 0) {
    nota(`${repr(cita)} no es nadie de la lista; por ahora quedó como tuyo.`);
    return [remitente, "baja"];
  }
  const persona = personas[0];
  if (!taxonomia.mencionaA(persona, remitente, texto)) {
    // La cita no está en el mensaje: el LLM la inventó.
    nota(`El mensaje no menciona a ${taxonomia.etiquetas[persona]}.`);
    return [persona, "baja"];
  }
  return [persona, confianza];
}

function explicarDudasSinNota(confianzas, notas) {
  for (const campo of CAMPOS) {
    if (confianzas[campo] !== "alta" && !notas.some((n) => n.campo === campo)) {
      notas.push({ campo, texto: `No estoy seguro de ${COMO_SE_LLAMA[campo]}.` });
    }
  }
}

/**
 * La compuerta: equivalente a parser.extraer() después de la llamada al LLM.
 *
 * `respuesta` es lo que el agente afirma; `texto`, `remitente` y `hoy` los
 * pone el workflow, nunca el LLM. `hoy` es "YYYY-MM-DD".
 */
function verificarGasto({ respuesta, texto, remitente, hoy, taxonomia }) {
  if (!taxonomia.personas.includes(remitente)) {
    // Error de configuración, no del LLM.
    throw new Error(
      `Remitente ${repr(remitente)} no es una persona de la taxonomía (${taxonomia.personas.join(", ")})`,
    );
  }
  const diaDeHoy = fechaDesdeIso(hoy);
  if (diaDeHoy === null) throw new Error(`hoy inválido: ${repr(hoy)}`);

  const r = validarRespuesta(respuesta);
  const notas = [];
  const [monto, confianzaMonto] = verificarMontoDe(r, texto, notas);
  const [categoria, confianzaCategoria] = verificarCategoriaDe(r, taxonomia, notas);
  const [fecha, confianzaFecha] = verificarFechaDe(r, diaDeHoy, notas);
  const [atribuidoA, confianzaAtribucion] = resolverAtribucion(
    r,
    texto,
    remitente,
    taxonomia,
    notas,
  );
  const confianzas = {
    monto: confianzaMonto,
    categoria: confianzaCategoria,
    fecha: confianzaFecha,
    atribuido_a: confianzaAtribucion,
  };
  explicarDudasSinNota(confianzas, notas);

  const camposDudosos = CAMPOS.filter((c) => confianzas[c] !== "alta");
  if (monto === null && !camposDudosos.includes("monto")) camposDudosos.unshift("monto");

  return {
    monto,
    categoria,
    fecha: fecha === null ? null : aIso(fecha),
    atribuido_a: atribuidoA,
    descripcion: strip(r.descripcion),
    texto_original: texto,
    remitente,
    confianza_monto: confianzaMonto,
    confianza_categoria: confianzaCategoria,
    confianza_fecha: confianzaFecha,
    confianza_atribuido_a: confianzaAtribucion,
    notas,
    campos_dudosos: camposDudosos,
    listo_para_guardar: monto !== null && camposDudosos.length === 0,
  };
}

// Piezas deterministas propias del workflow n8n: quién escribe, el hilo de la
// conversación, fallos visibles, filas a guardar y el reporte del mes.
//
// Igual que verificacion.js: funciones puras, sin globals de n8n. El build las
// pega en los Code nodes, después de verificacion.js.



// Única tool del agente. El reporte no es tool a propósito: los totales de la
// familia no pasan por el LLM (el agente solo pide `accion: "reporte"`).
const HERRAMIENTAS = ["verificar_gasto"];

/** La tool con la que el Agent de n8n entrega la salida estructurada. No es nuestra. */
const TOOL_SALIDA = "format_final_json_response";

const TTL_HILO_MS = 30 * 60 * 1000;
const MAX_MENSAJES_HILO = 5;

// --- Quién escribe (config.py: TELEGRAM_USUARIOS) ----------------------------

/**
 * "id:rol,id:rol" → { id: rol }. Falla rápido, igual que la versión Python:
 * una allowlist mal escrita no puede dejar pasar a nadie por accidente.
 */
function parsearUsuarios(texto, taxonomia) {
  const usuarios = {};
  for (const parte of (texto || "").split(",")) {
    if (!strip(parte)) continue;
    const i = parte.indexOf(":");
    const idCrudo = strip(i === -1 ? parte : parte.slice(0, i));
    const rol = i === -1 ? "" : strip(parte.slice(i + 1)).toLowerCase();
    if (i === -1 || !rol) {
      throw new Error(`TELEGRAM_USUARIOS: ${repr(strip(parte))} no tiene la forma id:rol`);
    }
    if (!/^\d+$/.test(idCrudo)) {
      throw new Error(`TELEGRAM_USUARIOS: ${repr(idCrudo)} no es un ID numérico`);
    }
    const id = String(BigInt(idCrudo));
    if (id in usuarios) throw new Error(`TELEGRAM_USUARIOS: el ID ${id} aparece dos veces`);
    if (!taxonomia.personas.includes(rol)) {
      throw new Error(
        `TELEGRAM_USUARIOS: el rol ${repr(rol)} no es una persona de la taxonomía ` +
          `(${taxonomia.personas.join(", ")})`,
      );
    }
    usuarios[id] = rol;
  }
  return usuarios;
}

/** Rol de quien escribe, o null si no está autorizado. */
function remitenteDe(idTelegram, usuarios) {
  if (idTelegram === null || idTelegram === undefined) return null;
  return usuarios[String(idTelegram)] ?? null;
}

// --- Hilo de conversación ------------------------------------------------------
//
// El monto se verifica contra lo que la persona escribió en el hilo abierto, no
// solo contra el último mensaje: si el agente preguntó "¿cuánto fue?", la
// respuesta "40" tiene que respaldar el monto. El hilo se cierra al terminar
// una propuesta (guardada o no) o una respuesta, así que un monto ya confirmado
// nunca respalda un gasto nuevo.
//
// `hilos` es el estado persistente del workflow ($getWorkflowStaticData).

/**
 * Agrega el mensaje al hilo del chat. Si el hilo anterior quedó abierto (el
 * agente preguntó y nadie respondió a tiempo), lo reporta como abandonado:
 * también cuenta para el reporte de calidad.
 *
 * `hiloId` es además la sesión de la memoria del agente: un hilo nuevo empieza
 * con la memoria vacía, sin tener que borrarla a mano.
 */
function agregarAlHilo(hilos, chatId, texto, ahoraMs) {
  const clave = String(chatId);
  const previo = hilos[clave];
  let abandonado = false;
  if (
    previo &&
    (ahoraMs - previo.ultimoMs > TTL_HILO_MS || previo.mensajes.length >= MAX_MENSAJES_HILO)
  ) {
    abandonado = true;
    delete hilos[clave];
  }
  const hilo = hilos[clave] || { id: `${clave}:${ahoraMs}`, mensajes: [], ultimoMs: ahoraMs };
  hilo.mensajes.push(texto);
  hilo.ultimoMs = ahoraMs;
  hilos[clave] = hilo;
  return { abandonado, hiloId: hilo.id, textoRespaldo: hilo.mensajes.join("\n") };
}

function cerrarHilo(hilos, chatId) {
  delete hilos[String(chatId)];
}

// --- Fallos visibles -----------------------------------------------------------

const MENSAJES = {
  procesando: "Leyendo tu mensaje...",
  cuota:
    "Por hoy ya no puedo leer más mensajes automáticamente " +
    "(se acabó la cuota gratuita del servicio). Intenta mañana.",
  timeout: "El servicio está lento y no alcanzó a responder. ¿Lo intentas de nuevo?",
  contrato: "No pude entender ese mensaje. ¿Me lo escribes de otra forma?",
  desconocido: "Algo falló de mi lado y no pude procesar tu mensaje. ¿Lo intentas de nuevo?",
  sinRegistro: "No registré ningún gasto con este mensaje.",
};

/**
 * Qué falló, en palabras de la persona. `error` es lo que n8n deja en la salida
 * de error del nodo del agente ({ message, description, httpCode, ... }).
 */
function clasificarFallo(error) {
  const e = typeof error === "string" ? { message: error } : error || {};
  const texto = [e.message, e.description, e.name, e.httpCode, e.code]
    .filter((v) => v !== undefined && v !== null)
    .join(" ");
  let motivo = "desconocido";
  // n8n reescribe el 429 del proveedor como "too many requests".
  if (/\b429\b|RESOURCE_EXHAUSTED|quota|too many requests/i.test(texto)) motivo = "cuota";
  else if (/timed? ?out|timeout|ETIMEDOUT|ECONNABORTED|aborted/i.test(texto)) motivo = "timeout";
  else if (/output parser|parse|contrato|schema|JSON/i.test(texto)) motivo = "contrato";
  return { motivo, mensaje: MENSAJES[motivo], detalle: texto.slice(0, 300) };
}

/** La tool responde con los items de su último nodo: un arreglo de un elemento. */
function interpretarObservacion(observacion) {
  let valor = observacion;
  if (typeof valor === "string") {
    try {
      valor = JSON.parse(valor);
    } catch {
      return null;
    }
  }
  if (Array.isArray(valor)) valor = valor.length === 1 ? valor[0] : null;
  if (valor && typeof valor === "object" && valor.json && typeof valor.json === "object") {
    valor = valor.json;
  }
  return valor && typeof valor === "object" ? valor : null;
}

/**
 * Revisa las llamadas a tools que hizo el agente. No se confía en que el agente
 * cuente sus propios problemas: una tool inexistente o caída queda registrada
 * y se le avisa a la persona.
 *
 * `pasos` son los intermediateSteps del nodo AI Agent: [{ action: { tool }, observation }].
 * Nuestras tools siempre responden JSON con `ok`; cualquier otra cosa es un fallo.
 */
function auditarPasos(pasos) {
  const problemas = [];
  for (const paso of pasos || []) {
    const tool = paso && paso.action ? paso.action.tool : undefined;
    if (tool === TOOL_SALIDA) continue;
    if (!HERRAMIENTAS.includes(tool)) {
      problemas.push({ tool: tool ?? null, motivo: "tool_inexistente" });
      continue;
    }
    const obs = interpretarObservacion(paso.observation);
    if (!obs || obs.ok !== true) {
      const detalle = obs && obs.error ? String(obs.error) : String(paso.observation ?? "");
      problemas.push({ tool, motivo: "tool_fallo", detalle: detalle.slice(0, 200) });
    }
  }
  return problemas;
}

function avisoDeProblemas(problemas) {
  if (!problemas.length) return null;
  const partes = problemas.map((p) =>
    p.motivo === "tool_inexistente"
      ? `intenté usar una herramienta que no existe (${p.tool ?? "sin nombre"})`
      : `la herramienta ${p.tool} falló`,
  );
  return (
    `⚠️ Aviso: ${partes.join("; ")}. ` +
    "Lo que te muestro lo revisó igual el verificador, pero cuéntale a quien mantiene el bot."
  );
}

/**
 * El agente puede decidir no proponer ningún gasto. Si el mensaje traía un
 * número, eso se dice y se registra: el agente no puede "olvidar" un gasto en silencio.
 */
function probableGastoNoRegistrado(accion, texto) {
  return accion !== "proponer" && montosEnTexto(texto).size > 0;
}

// --- Filas a guardar -----------------------------------------------------------

/**
 * Fila de `gastos`. Solo se llama desde la rama "aprobado" de la confirmación.
 * Repite las restricciones de la tabla SQL de Python: nada inválido entra aunque
 * alguien reconecte mal el workflow.
 */
function filaGasto(gasto, registradoPor, taxonomia, ahoraIso) {
  if (gasto.monto === null) throw new Error("No se guarda un gasto sin monto");
  if (!taxonomia.contiene(gasto.categoria)) {
    throw new Error(`Categoría ${repr(gasto.categoria)} no está activa en la taxonomía`);
  }
  if (!taxonomia.nombresAtribucion.includes(gasto.atribuido_a)) {
    throw new Error(`Atribución ${repr(gasto.atribuido_a)} no existe en la taxonomía`);
  }
  if (!gasto.fecha) throw new Error("No se guarda un gasto sin fecha");
  return {
    monto_centavos: aCentavos(gasto.monto),
    categoria: gasto.categoria,
    atribuido_a: gasto.atribuido_a,
    fecha: gasto.fecha,
    descripcion: gasto.descripcion.slice(0, 500),
    texto_original: gasto.texto_original,
    registrado_por: String(registradoPor),
    creado_en: ahoraIso,
    confianza_monto: gasto.confianza_monto,
    confianza_categoria: gasto.confianza_categoria,
    confianza_fecha: gasto.confianza_fecha,
    confianza_atribuido_a: gasto.confianza_atribuido_a,
    corregido_manualmente: false,
    anulado_en: null,
    motivo_anulacion: null,
  };
}

const RESULTADOS = [
  "confirmada", // la persona tocó "Sí, guardar"
  "rechazada", // tocó "No"
  "expirada", // nadie respondió a la confirmación a tiempo
  "no_ofrecible", // la compuerta no encontró monto: no se puede ofrecer guardar
  "no_propuesto", // el agente no propuso nada y el mensaje traía un número
  "abandonada", // el agente preguntó algo y nadie respondió
  "error_al_guardar", // la persona dijo que sí, pero la escritura falló
];

/**
 * Fila de `extracciones`: una por intento, se haya guardado o no (evita el
 * sesgo del superviviente). A propósito sin monto ni texto, como en Python.
 * Sin gasto verificado (no_propuesto, abandonada) las confianzas quedan null.
 */
function filaExtraccion(resultado, gasto, ahoraIso) {
  if (!RESULTADOS.includes(resultado)) throw new Error(`Resultado desconocido: ${repr(resultado)}`);
  const conf = (campo) => (gasto ? gasto[`confianza_${campo}`] : null);
  return {
    creado_en: ahoraIso,
    resultado,
    confirmada: resultado === "confirmada",
    corregida: false, // sin botones de corrección: corregir es rechazar y reescribir
    tenia_monto: Boolean(gasto && gasto.monto !== null),
    confianza_monto: conf("monto"),
    confianza_categoria: conf("categoria"),
    confianza_fecha: conf("fecha"),
    confianza_atribuido_a: conf("atribuido_a"),
  };
}

// --- Reporte del mes (dashboard/report.py) -------------------------------------

function rangoDelMes(anio, mes) {
  const ultimo = new Date(Date.UTC(anio, mes, 0)).getUTCDate();
  const dos = (n) => String(n).padStart(2, "0");
  return [`${anio}-${dos(mes)}-01`, `${anio}-${dos(mes)}-${dos(ultimo)}`];
}

/**
 * Totales del mes por categoría, de mayor a menor, sobre filas de `gastos`.
 * Excluye anulados. Empates: primero la categoría del gasto más reciente, igual
 * que Python (lista por fecha e id descendente y ordena de forma estable).
 */
function reporteMes(filas, anio, mes) {
  const [desde, hasta] = rangoDelMes(anio, mes);
  const delMes = (filas || [])
    .filter((f) => !f.anulado_en && f.fecha >= desde && f.fecha <= hasta)
    .sort((a, b) => (a.fecha === b.fecha ? Number(b.id) - Number(a.id) : a.fecha < b.fecha ? 1 : -1));

  const acumulado = new Map();
  for (const f of delMes) {
    const fila = acumulado.get(f.categoria) || { categoria: f.categoria, total_centavos: 0, cantidad: 0 };
    fila.total_centavos += Number(f.monto_centavos);
    fila.cantidad += 1;
    acumulado.set(f.categoria, fila);
  }
  const porCategoria = [...acumulado.values()].sort((a, b) => b.total_centavos - a.total_centavos);
  return {
    anio,
    mes,
    total_centavos: delMes.reduce((s, f) => s + Number(f.monto_centavos), 0),
    cantidad: delMes.length,
    por_categoria: porCategoria,
  };
}

/** calcular_calidad de report.py. Una confianza null nunca cuenta como alta. */
function calcularCalidad(extracciones) {
  const lista = extracciones || [];
  const sinDudas = lista.filter(
    (e) => e.tenia_monto && CAMPOS.every((c) => e[`confianza_${c}`] === "alta"),
  ).length;
  const confirmadas = lista.filter((e) => e.confirmada).length;
  const corregidas = lista.filter((e) => e.confirmada && e.corregida).length;
  return { intentos: lista.length, confirmadas, corregidas, sin_dudas: sinDudas };
}

// --- Presupuesto (config.py: ingresos, dashboard/presupuesto.py) ---------------

/**
 * "rol:monto,rol:monto" → { rol: "monto" }. Mismo formato estricto que Python:
 * dígitos y hasta dos decimales. Falla rápido, como la allowlist.
 */
function parsearIngresos(texto, taxonomia) {
  const ingresos = {};
  for (const parte of (texto || "").split(",")) {
    if (!strip(parte)) continue;
    const i = parte.indexOf(":");
    const rol = strip(i === -1 ? parte : parte.slice(0, i)).toLowerCase();
    const crudo = i === -1 ? "" : strip(parte.slice(i + 1));
    if (i === -1 || !rol) {
      throw new Error(`INGRESOS_MENSUALES: ${repr(strip(parte))} no tiene la forma rol:monto`);
    }
    if (!/^\d+(\.\d{1,2})?$/.test(crudo)) {
      throw new Error(
        `INGRESOS_MENSUALES: ${repr(crudo)} no es un monto (dígitos y hasta dos decimales, con punto)`,
      );
    }
    if (aCentavos0(crudo) <= 0) {
      throw new Error(`INGRESOS_MENSUALES: el ingreso de ${rol} debe ser positivo`);
    }
    if (rol in ingresos) throw new Error(`INGRESOS_MENSUALES: ${rol} aparece dos veces`);
    if (!taxonomia.personas.includes(rol)) {
      throw new Error(`INGRESOS_MENSUALES tiene roles que no son personas: ['${rol}']`);
    }
    ingresos[rol] = crudo;
  }
  if (Object.keys(ingresos).length && !taxonomia.bolsillos.length) {
    throw new Error("Hay INGRESOS_MENSUALES pero categories.yaml no define un presupuesto");
  }
  return ingresos;
}

function aCentavos0(monto) {
  const [entero, decimales = ""] = monto.split(".");
  return Number(entero) * 100 + Number(decimales.padEnd(2, "0") || "0");
}

/** Centavos exactos por bolsillo: truncados, y lo que sobra, de a uno a los primeros. */
function repartirCentavos(total, bolsillos) {
  const partes = bolsillos.map((b) => Math.floor((total * b.porcentaje) / 100));
  const sobra = total - partes.reduce((s, p) => s + p, 0);
  for (let i = 0; i < sobra; i++) partes[i % partes.length] += 1;
  return partes;
}

/**
 * Cuánto lleva gastado `persona` en cada bolsillo durante el mes, sobre filas de
 * `gastos`. Solo cuentan sus gastos (los atribuidos a ella) y no los anulados.
 */
function resumenPresupuesto(filas, taxonomia, persona, ingreso, anio, mes) {
  const [desde, hasta] = rangoDelMes(anio, mes);
  const suyas = (filas || [])
    .filter((f) => !f.anulado_en && f.atribuido_a === persona && f.fecha >= desde && f.fecha <= hasta)
    // Mismo orden que Python (fecha e id descendente): define el de "sin bolsillo".
    .sort((a, b) => (a.fecha === b.fecha ? Number(b.id) - Number(a.id) : a.fecha < b.fecha ? 1 : -1));

  const gastado = new Map();
  const sueltas = [];
  for (const f of suyas) {
    const bolsillo = taxonomia.bolsilloDe(f.categoria, f.texto_original);
    const acumulado = gastado.get(bolsillo) || { centavos: 0, cantidad: 0 };
    acumulado.centavos += Number(f.monto_centavos);
    acumulado.cantidad += 1;
    gastado.set(bolsillo, acumulado);
    if (bolsillo === null && !sueltas.includes(f.categoria)) sueltas.push(f.categoria);
  }

  const ingresoCentavos = aCentavos0(ingreso);
  const asignados = repartirCentavos(ingresoCentavos, taxonomia.bolsillos);
  return {
    persona,
    anio,
    mes,
    ingreso_centavos: ingresoCentavos,
    bolsillos: taxonomia.bolsillos.map((b, i) => ({
      nombre: b.nombre,
      etiqueta: b.etiqueta,
      porcentaje: b.porcentaje,
      se_gasta: b.se_gasta,
      asignado_centavos: asignados[i],
      gastado_centavos: (gastado.get(b.nombre) || { centavos: 0 }).centavos,
      cantidad: (gastado.get(b.nombre) || { cantidad: 0 }).cantidad,
    })),
    sin_bolsillo_centavos: (gastado.get(null) || { centavos: 0 }).centavos,
    categorias_sin_bolsillo: sueltas,
  };
}

/** Etiqueta del bolsillo de un gasto, si quien lo asume tiene presupuesto (handlers._bolsillo). */
function bolsilloVisible(taxonomia, ingresos, gasto) {
  if (!(gasto.atribuido_a in ingresos)) return null;
  const nombre = taxonomia.bolsilloDe(gasto.categoria, gasto.texto_original);
  const bolsillo = taxonomia.bolsillos.find((b) => b.nombre === nombre);
  return bolsillo ? bolsillo.etiqueta : "ninguno";
}

